package com.hbm.client.fel;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.machine.fel.*;import com.hbm.machine.silex.LaserWavelength;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.resources.sounds.SimpleSoundInstance;import net.minecraft.network.chat.Component;import net.minecraft.sounds.SoundEvents;import net.minecraft.world.entity.player.Inventory;import net.neoforged.neoforge.network.PacketDistributor;
/** Exact203x169 atlas, original title offsets/button/114px HEbar and5px GUI beam, native chosen font. */
public final class FelScreen extends LegacyContainerScreen<FelMenu> {
 public FelScreen(FelMenu menu,Inventory inventory,Component title){super(menu,inventory,title,FelContent.id("textures/gui/machine/gui_fel.png"),203,169);}
 private FelBlockEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position()) instanceof FelBlockEntity machine?machine:null;}
 @Override protected void renderLabels(GuiGraphics graphics,int x,int y){graphics.drawString(font,title,90+imageWidth/2-font.width(title)/2,7,0xffffff,false);graphics.drawString(font,playerInventoryTitle,8,71,4210752,false);var machine=machine();if(machine!=null&&machine.isOn)graphics.drawString(font,Component.translatable(machine.missingValidSilex?"gui.hbm.fel.error":"gui.hbm.fel.live"),(machine.missingValidSilex?55:54)+imageWidth/2-font.width(title)/2,9,machine.missingValidSilex?0xff0000:0x00ff00,false);}
 @Override protected void renderBg(GuiGraphics graphics,float partial,int x,int y){super.renderBg(graphics,partial,x,y);var machine=machine();if(machine==null)return;if(machine.isOn)drawLegacyRegion(graphics,142,41,203,0,29,17);int power=(int)(machine.getPower()*114/FelBlockEntity.MAX_POWER);if(power>0)drawLegacyRegion(graphics,182,27+113-power,203,17+113-power,16,power);
  if(machine.visuallyPowered()&&machine.distance>0){int color=machine.mode==LaserWavelength.VISIBLE?java.awt.Color.HSBtoRGB(machine.getLevel().getGameTime()/50F,.5F,1)&0xffffff:machine.mode.guiColor;graphics.fill(leftPos+113,topPos+29,leftPos+135,topPos+34,0xff000000|color);graphics.fill(0,topPos+29,leftPos+4,topPos+34,0xff000000|color);}
 }
 @Override public void render(GuiGraphics graphics,int x,int y,float partial){super.render(graphics,x,y,partial);var machine=machine();if(machine!=null&&legacyInfoHovered(x,y,182,27,16,113))graphics.renderTooltip(font,Component.literal(String.format(java.util.Locale.US,"%,d / %,d HE",machine.getPower(),FelBlockEntity.MAX_POWER)),x,y);}
 @Override public boolean mouseClicked(double x,double y,int button){boolean result=super.mouseClicked(x,y,button);if(legacyInfoHovered(x,y,142,41,29,17)){minecraft.getSoundManager().play(SimpleSoundInstance.forUI(SoundEvents.UI_BUTTON_CLICK,1));PacketDistributor.sendToServer(new FelControl(menu.containerId));return true;}return result;}
}
